// ============================================================
// Bloom Beauty Studio — Instagram Booking Bot
// Main conversation engine (n8n Code node v2 — uses helpers.httpRequest)
// ============================================================

const SUPABASE_URL = 'https://saajgmcaohjqtxufffid.supabase.co';
const SUPABASE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InNhYWpnbWNhb2hqcXR4dWZmZmlkIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3MzY5NDUxOSwiZXhwIjoyMDg5MjcwNTE5fQ.MhnKsCYqeIrOEryimCgXG4nMbvs2tlhs_oF6-jMMIa0';
const ACCESS_TOKEN = 'EAAfShrHKRZAcBQ7ZCq8iZCWQJdhRmZB3QiovTl5skE6nfXtM4OQl2Hf1zdlx7TG4f8qoXNZBJ5j7iKIfEggE5oP4Tb3O3kDtjmomslGRCz6n5gdZBZA2fdZAU8rwKjLRZBT7UifjSf9I8lN0vKgeQ35UY52Nvp75VnYIzJLGKfZBC32Tx8ZA5wnwPZBhzIm5x6nHd728WoBIuETvAgZDZD';

// --- Extract message data ---
const entry = $input.first().json.body.entry[0];
const messaging = entry.messaging[0];
const senderId = messaging.sender.id;
const messageObj = messaging.message;
const quickReplyPayload = messageObj.quick_reply?.payload || null;
const messageText = (messageObj.text || '').trim();
const msgLower = messageText.toLowerCase();

// --- Supabase REST helpers (using helpers.httpRequest) ---
async function supabaseGet(table, query = '') {
  return await helpers.httpRequest({
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/${table}?${query}`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    }
  });
}

async function supabasePost(table, data) {
  return await helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/${table}`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: data
  });
}

async function supabasePatch(table, query, data) {
  return await helpers.httpRequest({
    method: 'PATCH',
    url: `${SUPABASE_URL}/rest/v1/${table}?${query}`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: data
  });
}

async function supabaseRpc(fnName, args) {
  return await helpers.httpRequest({
    method: 'POST',
    url: `${SUPABASE_URL}/rest/v1/rpc/${fnName}`,
    headers: {
      'apikey': SUPABASE_KEY,
      'Authorization': `Bearer ${SUPABASE_KEY}`,
      'Content-Type': 'application/json'
    },
    body: args
  });
}

// --- Get or create client ---
let clients = await supabaseGet('clients', `instagram_id=eq.${senderId}`);
let client;
if (clients.length === 0) {
  const created = await supabasePost('clients', { instagram_id: senderId });
  client = Array.isArray(created) ? created[0] : created;
} else {
  client = clients[0];
}
const clientId = client.id;

// --- Get or create conversation ---
let convos = await supabaseGet('conversations', `client_id=eq.${clientId}`);
let convo;
if (convos.length === 0) {
  const created = await supabasePost('conversations', { client_id: clientId, current_step: 'GREETING' });
  convo = Array.isArray(created) ? created[0] : created;
} else {
  convo = convos[0];
}

let currentStep = convo.current_step;
let replyText = '';
let quickReplies = [];

// --- Helper: format date in Ukrainian ---
const DAY_NAMES = ['Нд', 'Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб'];
const MONTH_NAMES = ['січня', 'лютого', 'березня', 'квітня', 'травня', 'червня',
                     'липня', 'серпня', 'вересня', 'жовтня', 'листопада', 'грудня'];

function formatDate(dateStr) {
  const d = new Date(dateStr + 'T00:00:00');
  const day = DAY_NAMES[d.getDay()];
  const num = d.getDate();
  const month = MONTH_NAMES[d.getMonth()];
  return `${day}, ${num} ${month}`;
}

function formatTime(timeStr) {
  return timeStr.substring(0, 5); // HH:MM
}

// --- Category Quick Replies ---
const CATEGORIES = ['Ногті', 'Вії', 'Брови', 'Волосся'];
const CATEGORY_EMOJI = { 'Ногті': '💅', 'Вії': '👁', 'Брови': '✨', 'Волосся': '💇‍♀️' };

function categoryQuickReplies() {
  return CATEGORIES.map(cat => ({
    content_type: 'text',
    title: `${CATEGORY_EMOJI[cat] || ''} ${cat}`,
    payload: `CAT_${cat}`
  }));
}

// --- Update conversation state ---
async function updateConvo(fields) {
  fields.updated_at = new Date().toISOString();
  await supabasePatch('conversations', `client_id=eq.${clientId}`, fields);
}

// =========================
// SPECIAL COMMANDS (any step)
// =========================
const isCancel = /^(відміна|відмінити|заново|спочатку|скасувати|отмена|отменить|сначала)$/i.test(msgLower);
const isMyBookings = /^(мої записи|мои записи|записи)$/i.test(msgLower);
const isPriceList = /^(прайс|ціни|цены|цена|ціна|вартість|стоимость)$/i.test(msgLower);

if (isCancel) {
  await updateConvo({ current_step: 'GREETING', selected_category: null, selected_service_id: null, selected_master_id: null, selected_slot_id: null });
  replyText = 'Добре, почнемо спочатку! 🔄\n\nОберіть категорію послуг:';
  quickReplies = categoryQuickReplies();

} else if (isMyBookings) {
  const today = new Date().toISOString().split('T')[0];
  const bookings = await supabaseGet('bookings',
    `client_id=eq.${clientId}&status=eq.confirmed&date=gte.${today}&select=id,date,start_time,service_id(name,price),master_id(name)&order=date.asc,start_time.asc`);

  if (bookings.length === 0) {
    replyText = 'У вас поки немає активних записів. Бажаєте записатися? 😊';
    quickReplies = categoryQuickReplies();
  } else {
    replyText = '📋 Ваші записи:\n\n';
    bookings.forEach((b, i) => {
      const svcName = b.service_id?.name || 'Послуга';
      const masterName = b.master_id?.name || 'Майстер';
      replyText += `${i+1}. ${svcName} — ${masterName}\n   📅 ${formatDate(b.date)}, ${formatTime(b.start_time)}\n\n`;
    });
  }

} else if (isPriceList) {
  const services = await supabaseGet('services', 'is_active=eq.true&order=category.asc,price.asc');
  replyText = '💰 Прайс-лист Bloom Beauty Studio:\n\n';
  let lastCat = '';
  services.forEach(s => {
    if (s.category !== lastCat) {
      lastCat = s.category;
      replyText += `${CATEGORY_EMOJI[s.category] || ''} ${s.category}:\n`;
    }
    replyText += `  • ${s.name} — ${s.price} грн (${s.duration_minutes} хв)\n`;
  });
  replyText += '\nОберіть категорію для запису:';
  quickReplies = categoryQuickReplies();

// =========================
// MAIN CONVERSATION FLOW
// =========================
} else if (currentStep === 'GREETING') {
  // Check if user selected a category (via quick reply or text)
  let selectedCat = null;
  if (quickReplyPayload && quickReplyPayload.startsWith('CAT_')) {
    selectedCat = quickReplyPayload.replace('CAT_', '');
  } else {
    // Try to match category from text
    for (const cat of CATEGORIES) {
      if (msgLower.includes(cat.toLowerCase())) {
        selectedCat = cat;
        break;
      }
    }
  }

  if (selectedCat) {
    // User selected a category — move to SELECT_SERVICE
    const services = await supabaseGet('services', `category=eq.${encodeURIComponent(selectedCat)}&is_active=eq.true&order=price.asc`);

    if (services.length === 0) {
      replyText = `На жаль, послуг у категорії "${selectedCat}" зараз немає. Оберіть іншу категорію:`;
      quickReplies = categoryQuickReplies();
    } else {
      await updateConvo({ current_step: 'SELECT_SERVICE', selected_category: selectedCat });
      replyText = `${CATEGORY_EMOJI[selectedCat] || ''} Послуги — ${selectedCat}:\n\n`;
      services.forEach((s, i) => {
        replyText += `${i+1}. ${s.name} — ${s.price} грн (${s.duration_minutes} хв)\n`;
      });
      replyText += '\nОберіть послугу:';
      quickReplies = services.map(s => ({
        content_type: 'text',
        title: s.name,
        payload: `SVC_${s.id}`
      }));
    }
  } else {
    // First message or unrecognized — show greeting
    replyText = 'Привіт! 👋 Я бот-адміністратор Bloom Beauty Studio.\n\nМожу записати вас на процедуру. Оберіть категорію:';
    quickReplies = categoryQuickReplies();
  }

} else if (currentStep === 'SELECT_SERVICE') {
  // User should select a service
  let selectedServiceId = null;

  if (quickReplyPayload && quickReplyPayload.startsWith('SVC_')) {
    selectedServiceId = quickReplyPayload.replace('SVC_', '');
  } else {
    // Try to find service by name in selected category
    const services = await supabaseGet('services',
      `category=eq.${encodeURIComponent(convo.selected_category)}&is_active=eq.true`);
    const match = services.find(s => msgLower.includes(s.name.toLowerCase()));
    if (match) selectedServiceId = match.id;
  }

  if (!selectedServiceId) {
    replyText = 'Я не зрозумів вибір 🤔 Оберіть послугу зі списку або напишіть "спочатку" щоб почати заново.';
    // Re-show services
    const services = await supabaseGet('services',
      `category=eq.${encodeURIComponent(convo.selected_category)}&is_active=eq.true&order=price.asc`);
    quickReplies = services.map(s => ({
      content_type: 'text',
      title: s.name,
      payload: `SVC_${s.id}`
    }));
  } else {
    // Get masters who do this service
    const masterServices = await supabaseGet('master_services',
      `service_id=eq.${selectedServiceId}&select=master_id(id,name,is_active)`);
    const activeMasters = masterServices
      .map(ms => ms.master_id)
      .filter(m => m && m.is_active);

    if (activeMasters.length === 0) {
      replyText = 'На жаль, зараз немає вільних майстрів для цієї послуги. Спробуйте іншу послугу.';
      await updateConvo({ current_step: 'GREETING', selected_category: null });
      quickReplies = categoryQuickReplies();
    } else if (activeMasters.length === 1) {
      // Auto-select single master, go to SELECT_DATE
      const master = activeMasters[0];
      await updateConvo({
        current_step: 'SELECT_DATE',
        selected_service_id: selectedServiceId,
        selected_master_id: master.id
      });

      // Get available dates
      const today = new Date().toISOString().split('T')[0];
      const slots = await supabaseGet('schedule_slots',
        `master_id=eq.${master.id}&is_booked=eq.false&date=gte.${today}&order=date.asc&select=date`);

      const uniqueDates = [...new Set(slots.map(s => s.date))].slice(0, 5);

      if (uniqueDates.length === 0) {
        replyText = `Майстер ${master.name} — на жаль, немає вільних дат. Спробуйте іншу послугу.`;
        await updateConvo({ current_step: 'GREETING', selected_category: null, selected_service_id: null, selected_master_id: null });
        quickReplies = categoryQuickReplies();
      } else {
        replyText = `Ваш майстер: ${master.name} 👩‍🎨\n\nОберіть дату:`;
        quickReplies = uniqueDates.map(d => ({
          content_type: 'text',
          title: formatDate(d),
          payload: `DATE_${d}`
        }));
      }
    } else {
      // Multiple masters — let user choose
      await updateConvo({ current_step: 'SELECT_MASTER', selected_service_id: selectedServiceId });
      replyText = 'Оберіть майстра:\n\n';
      activeMasters.forEach((m, i) => {
        replyText += `${i+1}. ${m.name}\n`;
      });
      quickReplies = activeMasters.map(m => ({
        content_type: 'text',
        title: m.name,
        payload: `MASTER_${m.id}`
      }));
    }
  }

} else if (currentStep === 'SELECT_MASTER') {
  let selectedMasterId = null;

  if (quickReplyPayload && quickReplyPayload.startsWith('MASTER_')) {
    selectedMasterId = quickReplyPayload.replace('MASTER_', '');
  } else {
    // Try match by name
    const masterServices = await supabaseGet('master_services',
      `service_id=eq.${convo.selected_service_id}&select=master_id(id,name,is_active)`);
    const activeMasters = masterServices.map(ms => ms.master_id).filter(m => m && m.is_active);
    const match = activeMasters.find(m => msgLower.includes(m.name.toLowerCase()));
    if (match) selectedMasterId = match.id;
  }

  if (!selectedMasterId) {
    replyText = 'Я не зрозумів вибір 🤔 Оберіть майстра зі списку або напишіть "спочатку".';
    const masterServices = await supabaseGet('master_services',
      `service_id=eq.${convo.selected_service_id}&select=master_id(id,name,is_active)`);
    const activeMasters = masterServices.map(ms => ms.master_id).filter(m => m && m.is_active);
    quickReplies = activeMasters.map(m => ({
      content_type: 'text',
      title: m.name,
      payload: `MASTER_${m.id}`
    }));
  } else {
    await updateConvo({ current_step: 'SELECT_DATE', selected_master_id: selectedMasterId });

    const today = new Date().toISOString().split('T')[0];
    const slots = await supabaseGet('schedule_slots',
      `master_id=eq.${selectedMasterId}&is_booked=eq.false&date=gte.${today}&order=date.asc&select=date`);

    const uniqueDates = [...new Set(slots.map(s => s.date))].slice(0, 5);

    if (uniqueDates.length === 0) {
      replyText = 'На жаль, у цього майстра немає вільних дат. Спробуйте іншого майстра або іншу послугу.';
      await updateConvo({ current_step: 'GREETING', selected_category: null, selected_service_id: null, selected_master_id: null });
      quickReplies = categoryQuickReplies();
    } else {
      replyText = 'Оберіть зручну дату:';
      quickReplies = uniqueDates.map(d => ({
        content_type: 'text',
        title: formatDate(d),
        payload: `DATE_${d}`
      }));
    }
  }

} else if (currentStep === 'SELECT_DATE') {
  let selectedDate = null;

  if (quickReplyPayload && quickReplyPayload.startsWith('DATE_')) {
    selectedDate = quickReplyPayload.replace('DATE_', '');
  }

  if (!selectedDate) {
    replyText = 'Оберіть дату зі списку або напишіть "спочатку" щоб почати заново.';
    const today = new Date().toISOString().split('T')[0];
    const slots = await supabaseGet('schedule_slots',
      `master_id=eq.${convo.selected_master_id}&is_booked=eq.false&date=gte.${today}&order=date.asc&select=date`);
    const uniqueDates = [...new Set(slots.map(s => s.date))].slice(0, 5);
    quickReplies = uniqueDates.map(d => ({
      content_type: 'text',
      title: formatDate(d),
      payload: `DATE_${d}`
    }));
  } else {
    // Get service duration to find consecutive slots
    const svcArr = await supabaseGet('services', `id=eq.${convo.selected_service_id}`);
    const service = svcArr[0];
    const slotsNeeded = Math.ceil(service.duration_minutes / 30);

    // Get all free slots on this date for this master
    const allSlots = await supabaseGet('schedule_slots',
      `master_id=eq.${convo.selected_master_id}&date=eq.${selectedDate}&is_booked=eq.false&order=start_time.asc`);

    // Find consecutive groups
    const availableTimes = [];
    for (let i = 0; i <= allSlots.length - slotsNeeded; i++) {
      let consecutive = true;
      for (let j = 1; j < slotsNeeded; j++) {
        const prev = allSlots[i + j - 1];
        const curr = allSlots[i + j];
        if (prev.end_time !== curr.start_time) {
          consecutive = false;
          break;
        }
      }
      if (consecutive) {
        availableTimes.push(allSlots[i]);
      }
    }

    if (availableTimes.length === 0) {
      replyText = 'На жаль, на цю дату немає достатньо вільного часу для обраної послуги. Оберіть іншу дату:';
      const today = new Date().toISOString().split('T')[0];
      const slots = await supabaseGet('schedule_slots',
        `master_id=eq.${convo.selected_master_id}&is_booked=eq.false&date=gte.${today}&order=date.asc&select=date`);
      const uniqueDates = [...new Set(slots.map(s => s.date))].slice(0, 5);
      quickReplies = uniqueDates.map(d => ({
        content_type: 'text',
        title: formatDate(d),
        payload: `DATE_${d}`
      }));
    } else {
      // Store date context temporarily via slot selection
      await updateConvo({ current_step: 'SELECT_TIME' });

      replyText = `📅 ${formatDate(selectedDate)}\n\nОберіть час:`;
      quickReplies = availableTimes.slice(0, 13).map(s => ({
        content_type: 'text',
        title: formatTime(s.start_time),
        payload: `SLOT_${s.id}`
      }));
    }
  }

} else if (currentStep === 'SELECT_TIME') {
  let selectedSlotId = null;

  if (quickReplyPayload && quickReplyPayload.startsWith('SLOT_')) {
    selectedSlotId = quickReplyPayload.replace('SLOT_', '');
  }

  if (!selectedSlotId) {
    replyText = 'Оберіть час зі списку або напишіть "спочатку" щоб почати заново.';
  } else {
    // Get full details for confirmation
    const svcArr = await supabaseGet('services', `id=eq.${convo.selected_service_id}`);
    const masterArr = await supabaseGet('masters', `id=eq.${convo.selected_master_id}`);
    const slotArr = await supabaseGet('schedule_slots', `id=eq.${selectedSlotId}`);

    const service = svcArr[0];
    const master = masterArr[0];
    const slot = slotArr[0];

    await updateConvo({ current_step: 'CONFIRM', selected_slot_id: selectedSlotId });

    replyText = `📋 Ваш запис:\n\n` +
      `• Послуга: ${service.name}\n` +
      `• Майстер: ${master.name}\n` +
      `• Дата: ${formatDate(slot.date)}, ${formatTime(slot.start_time)}\n` +
      `• Вартість: ${service.price} грн\n` +
      `• Тривалість: ${service.duration_minutes} хв\n\n` +
      `Підтвердити?`;

    quickReplies = [
      { content_type: 'text', title: 'Так ✅', payload: 'CONFIRM_YES' },
      { content_type: 'text', title: 'Ні, спочатку 🔄', payload: 'CONFIRM_NO' }
    ];
  }

} else if (currentStep === 'CONFIRM') {
  const isYes = quickReplyPayload === 'CONFIRM_YES' ||
    /^(так|да|yes|підтверд)/i.test(msgLower);
  const isNo = quickReplyPayload === 'CONFIRM_NO' ||
    /^(ні|нет|no)/i.test(msgLower);

  if (isYes) {
    // Create booking
    const svcArr = await supabaseGet('services', `id=eq.${convo.selected_service_id}`);
    const service = svcArr[0];
    const slotArr = await supabaseGet('schedule_slots', `id=eq.${convo.selected_slot_id}`);
    const slot = slotArr[0];
    const slotsNeeded = Math.ceil(service.duration_minutes / 30);

    // Mark all consecutive slots as booked
    const allSlots = await supabaseGet('schedule_slots',
      `master_id=eq.${convo.selected_master_id}&date=eq.${slot.date}&start_time=gte.${slot.start_time}&is_booked=eq.false&order=start_time.asc&limit=${slotsNeeded}`);

    for (const s of allSlots) {
      await supabasePatch('schedule_slots', `id=eq.${s.id}`, { is_booked: true });
    }

    // Create booking record
    await supabasePost('bookings', {
      client_id: clientId,
      master_id: convo.selected_master_id,
      service_id: convo.selected_service_id,
      slot_id: convo.selected_slot_id,
      date: slot.date,
      start_time: slot.start_time,
      status: 'confirmed'
    });

    // Reset conversation
    await updateConvo({
      current_step: 'GREETING',
      selected_category: null,
      selected_service_id: null,
      selected_master_id: null,
      selected_slot_id: null
    });

    replyText = '✅ Готово! Вас записано.\n\n' +
      'Я нагадаю за 24 години до візиту.\n' +
      'Якщо потрібно скасувати або перенести — просто напишіть мені.\n\n' +
      'Бажаєте записатися ще на щось? 😊';
    quickReplies = categoryQuickReplies();

  } else if (isNo) {
    await updateConvo({
      current_step: 'GREETING',
      selected_category: null,
      selected_service_id: null,
      selected_master_id: null,
      selected_slot_id: null
    });
    replyText = 'Добре, почнемо спочатку! 🔄\n\nОберіть категорію послуг:';
    quickReplies = categoryQuickReplies();
  } else {
    replyText = 'Підтвердіть запис: Так ✅ або Ні 🔄';
    quickReplies = [
      { content_type: 'text', title: 'Так ✅', payload: 'CONFIRM_YES' },
      { content_type: 'text', title: 'Ні, спочатку 🔄', payload: 'CONFIRM_NO' }
    ];
  }

} else {
  // Unknown step — reset
  await updateConvo({ current_step: 'GREETING', selected_category: null, selected_service_id: null, selected_master_id: null, selected_slot_id: null });
  replyText = 'Щось пішло не так. Почнемо спочатку! 🔄\n\nОберіть категорію послуг:';
  quickReplies = categoryQuickReplies();
}

// --- Build Instagram message payload ---
const messagePayload = { text: replyText };
if (quickReplies.length > 0) {
  messagePayload.quick_replies = quickReplies.slice(0, 13);
}

return [{
  json: {
    senderId: senderId,
    messagePayload: messagePayload,
    accessToken: ACCESS_TOKEN
  }
}];
